// The course frontend. Vanilla JS, no build step, no server.
//
// - The course (chapters, cards, exercises with starter code, appended tests,
//   hints and solutions) comes from data/course.js, generated by
//   `cargo run -p course -- build`.
// - Exercises and code cards compile on the Rust Playground
//   (play.rust-lang.org), which allows cross-origin requests.
// - Progress and your code live in this browser's localStorage. Export and
//   Import in the sidebar move them between devices.
(function () {
  'use strict';

  const PLAYGROUND = 'https://play.rust-lang.org';
  const KEYS = {
    progress: 'rustcourse.progress',
    code: 'rustcourse.code.',
    unlocked: 'rustcourse.unlocked.',
  };

  const state = {
    course: null,
    progress: null,
    chapterId: null,
    showAll: false,
    // Per-exercise UI memory that survives re-renders.
    exercise: {}, // id -> { outcome, solution, running }
  };

  const $ = (sel, root) => (root || document).querySelector(sel);
  const el = (tag, attrs, ...children) => {
    const node = document.createElement(tag);
    if (attrs) {
      for (const [k, v] of Object.entries(attrs)) {
        if (k === 'class') node.className = v;
        else if (k === 'html') node.innerHTML = v;
        else if (k.startsWith('on') && typeof v === 'function') node.addEventListener(k.slice(2), v);
        else if (v !== null && v !== undefined && v !== false) node.setAttribute(k, v === true ? '' : v);
      }
    }
    for (const c of children.flat()) {
      if (c === null || c === undefined || c === false) continue;
      node.append(c instanceof Node ? c : document.createTextNode(String(c)));
    }
    return node;
  };

  const storage = {
    get(k, d) { try { const v = localStorage.getItem(k); return v === null ? d : JSON.parse(v); } catch (_) { return d; } },
    set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) { toast('Could not save: ' + e.message, 'error', 4000); } },
    getRaw(k) { try { return localStorage.getItem(k); } catch (_) { return null; } },
    setRaw(k, v) { try { localStorage.setItem(k, v); } catch (e) { toast('Could not save: ' + e.message, 'error', 4000); } },
    remove(k) { try { localStorage.removeItem(k); } catch (_) { /* ignore */ } },
    keys(prefix) { try { return Object.keys(localStorage).filter((k) => k.startsWith(prefix)); } catch (_) { return []; } },
  };

  // ------------------------------------------------------------------
  // Progress model (XP rules: a card pays full XP on a first-try answer and
  // half afterwards, never twice; an exercise pays once, on its first pass,
  // half if the solution was revealed before).
  // ------------------------------------------------------------------

  function emptyProgress() { return { xp: 0, cards: {}, exercises: {} }; }

  function normaliseProgress(p) {
    if (!p || typeof p !== 'object') return null;
    if (!('xp' in p) && !('cards' in p) && !('exercises' in p)) return null;
    return {
      xp: Number(p.xp) || 0,
      cards: p.cards && typeof p.cards === 'object' ? p.cards : {},
      exercises: p.exercises && typeof p.exercises === 'object' ? p.exercises : {},
    };
  }

  function saveProgress() { storage.set(KEYS.progress, state.progress); }

  function levelIndex(xp) {
    let idx = 0;
    state.course.levels.forEach((l, i) => { if (l.xp <= xp) idx = i; });
    return idx;
  }

  function answerCard(cardId, cardXp, correct) {
    const p = state.progress;
    const before = levelIndex(p.xp);
    const entry = p.cards[cardId] || (p.cards[cardId] = { done: false, attempts: 0, first_try: false, xp_awarded: 0 });
    let gained = 0;
    if (!entry.done) {
      entry.attempts += 1;
      if (correct) {
        entry.done = true;
        entry.first_try = entry.attempts === 1;
        gained = entry.first_try ? cardXp : Math.ceil(cardXp / 2);
        entry.xp_awarded = gained;
        p.xp += gained;
      }
    }
    saveProgress();
    return { xp_gained: gained, xp_total: p.xp, level_before: before, level_after: levelIndex(p.xp) };
  }

  function exerciseEntry(id) {
    const p = state.progress;
    return p.exercises[id] || (p.exercises[id] = {
      passed: false, attempts: 0, hints_revealed: 0, solution_revealed: false, xp_awarded: 0, last_status: '',
    });
  }

  function exerciseProgress(id) {
    return state.progress.exercises[id] || { passed: false, attempts: 0, hints_revealed: 0, solution_revealed: false, xp_awarded: 0, last_status: '' };
  }

  function recordRun(id, exerciseXp, passed, status) {
    const p = state.progress;
    const before = levelIndex(p.xp);
    const entry = exerciseEntry(id);
    entry.attempts += 1;
    entry.last_status = status;
    let gained = 0;
    if (passed && !entry.passed) {
      entry.passed = true;
      gained = entry.solution_revealed ? Math.ceil(exerciseXp / 2) : exerciseXp;
      entry.xp_awarded = gained;
      p.xp += gained;
    }
    saveProgress();
    return { xp_gained: gained, xp_total: p.xp, level_before: before, level_after: levelIndex(p.xp) };
  }

  function revealHint(id, n) {
    const entry = exerciseEntry(id);
    entry.hints_revealed = Math.max(entry.hints_revealed || 0, n);
    saveProgress();
  }

  function revealSolution(id) {
    exerciseEntry(id).solution_revealed = true;
    saveProgress();
  }

  // Code buffers. Project stages share one buffer (their source_key).
  const code = {
    get(ex) { const v = storage.getRaw(KEYS.code + ex.source_key); return v === null ? ex.starter : v; },
    set(ex, text) { storage.setRaw(KEYS.code + ex.source_key, text); },
    reset(ex) { storage.remove(KEYS.code + ex.source_key); },
    all() {
      const out = {};
      for (const k of storage.keys(KEYS.code)) out[k.slice(KEYS.code.length)] = storage.getRaw(k);
      return out;
    },
    clearAll() { for (const k of storage.keys(KEYS.code)) storage.remove(k); },
  };

  // ------------------------------------------------------------------
  // Export / import
  // ------------------------------------------------------------------

  function exportProgress() {
    const stamp = new Date().toISOString().slice(0, 10);
    const data = {
      format: 'rustcourse-progress',
      version: 1,
      exported_at: new Date().toISOString(),
      progress: state.progress,
      code: code.all(),
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = el('a', { href: url, download: 'rustcourse-progress-' + stamp + '.json' });
    document.body.append(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 2000);
    toast('Progress exported');
  }

  async function importProgress(file) {
    let data;
    try {
      data = JSON.parse(await file.text());
    } catch (e) {
      toast('That file is not valid JSON', 'error', 4000);
      return;
    }
    let progress = null;
    let codeMap = null;
    if (data && data.format === 'rustcourse-progress') {
      progress = normaliseProgress(data.progress);
      codeMap = data.code && typeof data.code === 'object' ? data.code : {};
    } else {
      // A bare progress.json from the earlier, server-based version.
      progress = normaliseProgress(data);
    }
    if (!progress) {
      toast('That file does not look like course progress', 'error', 4000);
      return;
    }
    const cards = Object.values(progress.cards).filter((c) => c && c.done).length;
    const passed = Object.values(progress.exercises).filter((e) => e && e.passed).length;
    const ok = await confirmDialog('Import this progress?',
      progress.xp + ' XP, ' + cards + ' cards answered, ' + passed + ' exercises passed' +
      (codeMap ? ', code for ' + Object.keys(codeMap).length + ' exercises' : '') +
      '. It replaces what is in this browser now.', 'Import');
    if (!ok) return;
    state.progress = progress;
    saveProgress();
    if (codeMap) {
      code.clearAll();
      for (const [k, v] of Object.entries(codeMap)) if (typeof v === 'string') storage.setRaw(KEYS.code + k, v);
    }
    state.exercise = {};
    route();
    toast('Progress imported');
  }

  // ------------------------------------------------------------------
  // The Playground
  // ------------------------------------------------------------------

  async function playground(source, tests) {
    let res;
    try {
      res = await fetch(PLAYGROUND + '/execute', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          channel: 'stable', mode: 'debug', edition: '2024',
          crateType: tests ? 'lib' : 'bin', tests, code: source, backtrace: false,
        }),
      });
    } catch (e) {
      throw new Error('Could not reach play.rust-lang.org. Are you online?');
    }
    if (!res.ok) {
      const text = await res.text().catch(() => '');
      throw new Error('The Playground answered HTTP ' + res.status + (text ? ': ' + text.slice(0, 200) : ''));
    }
    return res.json();
  }

  // Mirrors course/src/online.rs: a pass needs exit status 0 and the test
  // harness summary; compile errors are recognised from stderr.
  function classify(r) {
    if (r.success && /test result: ok/.test(r.stdout || '')) return 'passed';
    const err = r.stderr || '';
    if (/could not compile|error\[E|error: expected|error: cannot/.test(err)) return 'compile_error';
    return 'failed';
  }

  function combined(source, tests) {
    return tests ? source.replace(/\s+$/, '') + '\n\n' + tests : source;
  }

  function playgroundUrl(source) {
    return PLAYGROUND + '/?version=stable&mode=debug&edition=2024&code=' + encodeURIComponent(source);
  }

  // Source-level requirements (mirrors course/src/runner.rs).
  function stripComments(src) {
    return src.split('\n').map((l) => { const i = l.indexOf('//'); return i >= 0 ? l.slice(0, i) : l; }).join('\n');
  }

  function countTests(src) {
    return src.split('\n')
      .map((l) => l.trimStart())
      .filter((l) => !l.startsWith('//'))
      .filter((l) => l.startsWith('#[test]') || l.startsWith('#[test ') || l.startsWith('#[tokio::test'))
      .length;
  }

  function extraChecks(req, source) {
    const checks = [];
    if (!req) return checks;
    if (req.min_tests > 0) {
      const n = countTests(source);
      checks.push({ label: 'at least ' + req.min_tests + ' #[test] functions (found ' + n + ')', ok: n >= req.min_tests });
    }
    const body = stripComments(source);
    for (const needle of req.must_contain || []) checks.push({ label: 'file uses `' + needle + '`', ok: body.includes(needle) });
    for (const needle of req.must_not_contain || []) checks.push({ label: 'file does not use `' + needle + '`', ok: !body.includes(needle) });
    return checks;
  }

  // ------------------------------------------------------------------
  // Progress helpers
  // ------------------------------------------------------------------

  function cardDone(card) {
    if (card.type === 'exercise') return !!exerciseProgress(card.ref).passed;
    const c = state.progress.cards[card.id];
    return !!(c && c.done);
  }

  function chapterStats(ch) {
    const total = ch.cards.length;
    const done = ch.cards.filter(cardDone).length;
    const exercises = ch.cards.filter((c) => c.type === 'exercise');
    const exDone = exercises.filter(cardDone).length;
    return { total, done, exTotal: exercises.length, exDone, complete: total > 0 && done === total };
  }

  function suggestedChapter() {
    return state.course.chapters.find((ch) => ch.cards.length && !chapterStats(ch).complete) || null;
  }

  function levelInfo() {
    const levels = state.course.levels;
    const xp = state.progress.xp;
    const idx = levelIndex(xp);
    const cur = levels[idx];
    const next = levels[idx + 1] || null;
    const pct = next ? Math.min(100, Math.round(((xp - cur.xp) / (next.xp - cur.xp)) * 100)) : 100;
    return { idx, cur, next, pct, xp };
  }

  // ------------------------------------------------------------------
  // Toasts & dialogs
  // ------------------------------------------------------------------

  function toast(text, cls, ms) {
    const node = el('div', { class: 'toast ' + (cls || '') }, text);
    $('#toasts').append(node);
    setTimeout(() => node.remove(), ms || 2600);
  }

  function handleAward(award) {
    if (!award) return;
    if (award.xp_gained > 0) toast('+' + award.xp_gained + ' XP', 'xp');
    if (award.level_after > award.level_before) {
      const lvl = state.course.levels[award.level_after];
      setTimeout(() => toast('Level up: ' + lvl.title, 'level', 4000), 350);
    }
    renderSidebar();
  }

  function confirmDialog(title, text, okLabel) {
    return new Promise((resolve) => {
      const root = $('#dialog-root');
      const close = (v) => { root.innerHTML = ''; resolve(v); };
      const box = el('div', { class: 'dialog', role: 'dialog', 'aria-modal': 'true' },
        el('h3', null, title),
        el('p', null, text),
        el('div', { class: 'row' },
          el('button', { class: 'btn', onclick: () => close(false) }, 'Cancel'),
          el('button', { class: 'btn primary', onclick: () => close(true) }, okLabel || 'OK')));
      const backdrop = el('div', { class: 'dialog-backdrop', onclick: (e) => { if (e.target === backdrop) close(false); } }, box);
      root.append(backdrop);
    });
  }

  // ------------------------------------------------------------------
  // Sidebar
  // ------------------------------------------------------------------

  function ring(done, total) {
    const r = 13, c = 2 * Math.PI * r;
    const frac = total ? done / total : 0;
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('viewBox', '0 0 32 32');
    svg.setAttribute('class', 'ring' + (total && done === total ? ' done' : ''));
    svg.innerHTML =
      '<circle class="track" cx="16" cy="16" r="' + r + '" fill="none" stroke-width="3"></circle>' +
      '<circle class="fill" cx="16" cy="16" r="' + r + '" fill="none" stroke-width="3" stroke-linecap="round" ' +
      'stroke-dasharray="' + c.toFixed(2) + '" stroke-dashoffset="' + (c * (1 - frac)).toFixed(2) + '" transform="rotate(-90 16 16)"></circle>' +
      (total && done === total
        ? '<text x="16" y="20.5" text-anchor="middle">✓</text>'
        : '<text x="16" y="20" text-anchor="middle">' + Math.round(frac * 100) + '</text>');
    return svg;
  }

  function renderSidebar() {
    const info = levelInfo();
    $('#level-title').textContent = info.cur.title;
    $('#xp-fill').style.width = info.pct + '%';
    $('#xp-text').textContent = info.next
      ? info.xp + ' XP · ' + (info.next.xp - info.xp) + ' to ' + info.next.title
      : info.xp + ' XP · max level';

    const list = $('#chapter-list');
    list.innerHTML = '';
    const next = suggestedChapter();
    for (const ch of state.course.chapters) {
      const s = chapterStats(ch);
      const btn = el('button', {
        class: 'chapter-link' + (ch.id === state.chapterId ? ' active' : '') + (ch.cards.length ? '' : ' empty'),
        onclick: () => { location.hash = '#/' + ch.id; $('#sidebar').classList.remove('open'); },
      },
        ring(s.done, s.total),
        el('span', { class: 'chapter-link-text' },
          el('span', { class: 'chapter-link-title' }, ch.number + '. ' + ch.title),
          el('span', { class: 'chapter-link-sub' }, ch.cards.length ? s.done + '/' + s.total + ' done' : 'coming soon')),
        next && next.id === ch.id ? el('span', { class: 'next-pill' }, 'next') : null);
      list.append(btn);
    }
  }

  // ------------------------------------------------------------------
  // Home
  // ------------------------------------------------------------------

  function renderHome() {
    const main = $('#content');
    main.innerHTML = '';
    const next = suggestedChapter();
    const totalDone = state.course.chapters.reduce((n, ch) => n + chapterStats(ch).done, 0);
    const total = state.course.chapters.reduce((n, ch) => n + ch.cards.length, 0);
    main.append(
      el('div', { class: 'chapter-header' },
        el('div', { class: 'chapter-kicker' }, 'Interactive edition'),
        el('h1', null, state.course.title),
        el('p', { class: 'chapter-subtitle' },
          'Lessons, predictions and quizzes, with exercises you write in the browser and check on the Rust Playground.'),
        el('div', { class: 'chapter-stats' },
          el('span', null, el('strong', null, state.progress.xp), ' XP earned of ', state.course.total_xp),
          el('span', null, el('strong', null, totalDone), ' of ', total, ' cards done'))),
      next ? el('div', { class: 'row' },
        el('button', { class: 'btn primary', onclick: () => { location.hash = '#/' + next.id; } },
          'Continue: ' + next.number + '. ' + next.title)) : null,
      el('div', { class: 'home-grid' },
        state.course.chapters.map((ch) => {
          const s = chapterStats(ch);
          return el('button', {
            class: 'home-card' + (ch.cards.length ? '' : ' soon'),
            onclick: () => { if (ch.cards.length) location.hash = '#/' + ch.id; },
          },
            el('div', { class: 'num' }, 'Chapter ' + ch.number + (s.complete ? ' · complete' : '')),
            el('div', { class: 't' }, ch.title),
            el('div', { class: 's' }, ch.cards.length ? ch.subtitle + ' · ' + s.exTotal + ' exercises' : 'Coming soon'));
        })),
      el('p', { class: 'muted', style: 'margin-top:28px' },
        'Progress is saved in this browser. Use Export in the sidebar to carry it to another device, and Import there.'));
  }

  // ------------------------------------------------------------------
  // Chapter
  // ------------------------------------------------------------------

  function unlockedKey(chId) { return KEYS.unlocked + chId; }

  function renderChapter(ch) {
    const main = $('#content');
    main.innerHTML = '';
    const s = chapterStats(ch);

    const firstUndone = ch.cards.findIndex((c) => !cardDone(c));
    const manuallyUnlocked = storage.get(unlockedKey(ch.id), -1);
    const frontier = state.showAll ? Infinity : Math.max(firstUndone === -1 ? ch.cards.length : firstUndone, manuallyUnlocked);

    const showAllToggle = el('label', { class: 'toggle' },
      el('input', { type: 'checkbox', checked: state.showAll, onchange: (e) => { state.showAll = e.target.checked; renderChapter(ch); } }),
      'Show every card');

    main.append(
      el('div', { class: 'chapter-header' },
        el('div', { class: 'chapter-kicker' }, 'Chapter ' + ch.number + (ch.book ? ' · Book ' + ch.book : '')),
        el('h1', null, ch.title),
        el('p', { class: 'chapter-subtitle' }, ch.subtitle),
        chapterStatsRow(ch)),
      el('div', { class: 'toolbar' }, showAllToggle));

    ch.cards.forEach((card, idx) => {
      const done = cardDone(card);
      const locked = idx > frontier;
      const expanded = !locked && (idx === frontier || (!done && idx <= frontier));
      main.append(renderCard(ch, card, idx, { done, locked, expanded }));
    });

    if (s.complete) {
      const nextCh = state.course.chapters.find((c) => c.number > ch.number && c.cards.length);
      main.append(el('div', { class: 'chapter-end' },
        el('div', null, '🎉'),
        el('h2', null, 'Chapter ' + ch.number + ' complete'),
        el('p', null, 'Every card answered and every exercise green.'),
        nextCh ? el('button', { class: 'btn primary', onclick: () => { location.hash = '#/' + nextCh.id; } },
          'On to ' + nextCh.number + '. ' + nextCh.title) : null));
    }
  }

  function chapterStatsRow(ch) {
    const s = chapterStats(ch);
    const xp = ch.cards.reduce((n, c) => n + (c.xp || 0), 0) +
      ch.cards.filter((c) => c.type === 'exercise').reduce((n, c) => n + (exerciseById(c.ref).xp || 0), 0);
    return el('div', { class: 'chapter-stats', id: 'chapter-stats' },
      el('span', null, el('strong', null, s.done), ' / ', s.total, ' cards'),
      el('span', null, el('strong', null, s.exDone), ' / ', s.exTotal, ' exercises'),
      el('span', null, el('strong', null, xp), ' XP available'));
  }

  // Refreshes the header counts without re-rendering the cards.
  function refreshChapterStats(ch) {
    const old = $('#chapter-stats');
    if (old) old.replaceWith(chapterStatsRow(ch));
  }

  function exerciseById(id) {
    return state.course.exercises.find((e) => e.id === id) ||
      { id, title: id, xp: 0, kind: '?', description: '', file: '', hints: [], starter: '', tests: null, solution: '', source_key: id, requires: {} };
  }

  function typeLabel(card) {
    return { read: 'Read', code: 'Try it', predict: 'Predict', quiz: 'Quiz', exercise: 'Exercise' }[card.type] || card.type;
  }

  function cardTitle(card) {
    if (card.type === 'exercise') return exerciseById(card.ref).title;
    return card.title || typeLabel(card);
  }

  function cardXp(card) {
    return card.type === 'exercise' ? exerciseById(card.ref).xp : card.xp;
  }

  function renderCard(ch, card, idx, opts) {
    const node = el('div', {
      class: 'card' + (opts.done ? ' done' : '') + (opts.locked ? ' locked' : '') + (opts.expanded ? '' : ' collapsed'),
      id: 'card-' + card.id,
    });
    const head = el('div', { class: 'card-head', onclick: () => { if (!opts.locked) node.classList.toggle('collapsed'); } },
      el('span', { class: 'card-type ' + card.type }, typeLabel(card)),
      el('span', { class: 'card-title' }, cardTitle(card)),
      el('span', { class: 'card-meta' }, cardXp(card) + ' XP'),
      el('span', { class: 'card-check' }, '✓'));
    node.append(head);

    const body = el('div', { class: 'card-body' });
    node.append(body);
    if (opts.locked) return node;

    switch (card.type) {
      case 'read': renderRead(ch, card, body, opts); break;
      case 'code': renderCode(ch, card, body, opts); break;
      case 'predict': renderPredict(ch, card, body, opts); break;
      case 'quiz': renderQuiz(ch, card, body, opts); break;
      case 'exercise': renderExercise(ch, card, body, opts); break;
    }
    return node;
  }

  function completeCard(ch, card, correct) {
    const award = answerCard(card.id, card.xp || 0, correct);
    handleAward(award);
    refreshChapterStats(ch);
    return award;
  }

  function unlockNext(ch, card) {
    const idx = ch.cards.indexOf(card);
    const cur = storage.get(unlockedKey(ch.id), -1);
    if (idx + 1 > cur) storage.set(unlockedKey(ch.id), idx + 1);
  }

  function advance(ch, card) {
    unlockNext(ch, card);
    renderChapter(ch);
    const idx = ch.cards.indexOf(card);
    const next = ch.cards[idx + 1];
    const target = next ? $('#card-' + CSS.escape(next.id)) : null;
    if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  function continueButton(ch, card, label, onDone) {
    return el('div', { class: 'continue-row' },
      el('button', {
        class: 'btn primary',
        onclick: (e) => {
          e.target.disabled = true;
          if (onDone) onDone();
          advance(ch, card);
        },
      }, label));
  }

  // --- read -------------------------------------------------------------

  function renderRead(ch, card, body, opts) {
    body.append(el('div', { html: md.render(card.body) }));
    if (!opts.done) {
      body.append(continueButton(ch, card, 'Got it', () => completeCard(ch, card, true)));
    }
  }

  // --- code -------------------------------------------------------------

  function renderCode(ch, card, body, opts) {
    const term = el('div', { class: 'term' });
    const runBtn = el('button', {
      class: 'btn primary small',
      onclick: async () => {
        runBtn.disabled = true;
        term.innerHTML = '<span class="dim">Compiling on play.rust-lang.org…</span>';
        try {
          const r = await playground(card.code, false);
          let html = '';
          const err = stripPlaygroundNoise(r.stderr || '');
          if (err) html += '<span class="' + (r.success ? 'warn' : 'err') + '">' + linkifyErrors(err) + '</span>\n';
          html += md.escapeHtml(r.stdout || '');
          if (!(r.stdout || '').trim() && r.success) html += '<span class="dim">(no output)</span>';
          term.innerHTML = html.trim() || '<span class="dim">(no output)</span>';
        } catch (e) {
          term.innerHTML = '<span class="err">' + md.escapeHtml(e.message) + '</span>\n<span class="dim">You can still read the code and move on.</span>';
        }
        runBtn.disabled = false;
      },
    }, '▶ Run');
    body.append(
      el('pre', { class: 'code lang-rust', html: '<code>' + hl.rust(card.code) + '</code>' }),
      el('div', { class: 'row' },
        runBtn,
        el('a', { class: 'btn small', href: playgroundUrl(card.code), target: '_blank', rel: 'noopener' }, 'Open in Playground ↗'),
        el('span', { class: 'muted' }, 'Runs on play.rust-lang.org')),
      term,
      card.body ? el('div', { html: md.render(card.body) }) : null);
    if (!opts.done) {
      body.append(continueButton(ch, card, 'Continue', () => completeCard(ch, card, true)));
    }
  }

  function stripPlaygroundNoise(stderr) {
    return stderr
      .split('\n')
      .filter((l) => !/^\s*(Compiling|Finished|Running|Standard Error|Standard Output)/.test(l))
      .join('\n')
      .trim();
  }

  // --- predict ----------------------------------------------------------

  function renderPredict(ch, card, body, opts) {
    body.append(el('pre', { class: 'code lang-rust', html: '<code>' + hl.rust(card.code) + '</code>' }));
    body.append(el('div', { class: 'question', html: md.inline(card.question || 'What happens?') }));
    renderChoice(ch, card, body, opts, false);
  }

  // --- quiz -------------------------------------------------------------

  function renderQuiz(ch, card, body, opts) {
    if (card.body) body.append(el('div', { html: md.render(card.body) }));
    body.append(el('div', { class: 'question', html: md.inline(card.question) }));
    if (card.answers && card.answers.length) renderFill(ch, card, body, opts);
    else renderChoice(ch, card, body, opts, card.multi);
  }

  function renderChoice(ch, card, body, opts, multi) {
    const selected = new Set();
    const buttons = card.options.map((opt, i) => el('button', {
      class: 'option' + (multi ? ' multi' : ''),
      onclick: () => {
        if (opts.done) return;
        if (multi) {
          if (selected.has(i)) selected.delete(i); else selected.add(i);
          buttons[i].classList.toggle('selected', selected.has(i));
          checkBtn.disabled = selected.size === 0;
        } else {
          selected.clear(); selected.add(i);
          submit();
        }
      },
    }, el('span', { class: 'bullet' }), el('span', { html: md.inline(opt.text) })));

    const feedback = el('div');
    const checkBtn = multi ? el('button', { class: 'btn primary', disabled: true, onclick: () => submit() }, 'Check') : null;

    function reveal(correct) {
      card.options.forEach((opt, i) => {
        const b = buttons[i];
        b.disabled = true;
        b.classList.remove('selected');
        if (selected.has(i) && opt.correct) b.classList.add('correct');
        else if (selected.has(i) && !opt.correct) b.classList.add('wrong');
        else if (!selected.has(i) && opt.correct && correct) b.classList.add('correct');
      });
      feedback.innerHTML = '';
      feedback.append(el('div', { class: 'feedback ' + (correct ? 'good' : 'bad') },
        el('div', { class: 'verdict' }, correct ? 'Correct' : 'Not quite'),
        correct ? el('div', { html: md.render(card.explanation) }) : el('p', null, multi ? 'Some of your picks are off. Try a different combination.' : 'Try another option.')));
    }

    function submit() {
      const correct = card.options.every((opt, i) => opt.correct === selected.has(i));
      reveal(correct);
      if (checkBtn) checkBtn.disabled = true;
      completeCard(ch, card, correct);
      if (correct) {
        $('#card-' + CSS.escape(card.id)).classList.add('done', 'flash');
        feedback.append(continueButton(ch, card, 'Continue'));
      } else {
        // Let them try again.
        setTimeout(() => {
          card.options.forEach((_, i) => {
            buttons[i].disabled = false;
            buttons[i].classList.remove('wrong', 'correct');
          });
          selected.clear();
          if (checkBtn) checkBtn.disabled = true;
        }, 900);
      }
    }

    body.append(el('div', { class: 'options' }, buttons));
    if (checkBtn) body.append(el('div', { class: 'row' }, checkBtn));
    body.append(feedback);

    if (opts.done) {
      card.options.forEach((opt, i) => { buttons[i].disabled = true; if (opt.correct) buttons[i].classList.add('correct'); });
      if (checkBtn) checkBtn.remove();
      feedback.append(el('div', { class: 'feedback good' },
        el('div', { class: 'verdict' }, 'Answered'),
        el('div', { html: md.render(card.explanation) })));
    }
  }

  function renderFill(ch, card, body, opts) {
    const input = el('input', { class: 'fill-input', type: 'text', placeholder: 'Type your answer', autocomplete: 'off', spellcheck: 'false' });
    const feedback = el('div');
    const btn = el('button', { class: 'btn primary', onclick: () => submit() }, 'Check');
    input.addEventListener('keydown', (e) => { if (e.key === 'Enter') submit(); });

    const normalise = (s) => s.trim().toLowerCase().replace(/^`|`$/g, '').replace(/\s+/g, ' ');

    function submit() {
      const given = normalise(input.value);
      if (!given) return;
      const correct = card.answers.some((a) => normalise(a) === given);
      feedback.innerHTML = '';
      feedback.append(el('div', { class: 'feedback ' + (correct ? 'good' : 'bad') },
        el('div', { class: 'verdict' }, correct ? 'Correct' : 'Not quite'),
        correct ? el('div', { html: md.render(card.explanation) }) : el('p', null, 'Try again.')));
      completeCard(ch, card, correct);
      if (correct) {
        input.disabled = true; btn.disabled = true;
        $('#card-' + CSS.escape(card.id)).classList.add('done', 'flash');
        feedback.append(continueButton(ch, card, 'Continue'));
      }
    }

    body.append(el('div', { class: 'row' }, input, btn), feedback);
    if (opts.done) {
      input.value = card.answers[0]; input.disabled = true; btn.disabled = true;
      feedback.append(el('div', { class: 'feedback good' },
        el('div', { class: 'verdict' }, 'Answered'),
        el('div', { html: md.render(card.explanation) })));
    }
  }

  // --- exercise -----------------------------------------------------------

  function exState(id) {
    if (!state.exercise[id]) state.exercise[id] = { outcome: null, solution: null, running: false };
    return state.exercise[id];
  }

  function linkifyErrors(text) {
    return md.escapeHtml(text)
      .replace(/error\[(E\d{4})\]/g, (m, code) =>
        '<a href="https://doc.rust-lang.org/error_codes/' + code + '.html" target="_blank" rel="noopener">' + m + '</a>');
  }

  // `cargo test` on a library compiles it twice (once for the tests, once
  // plain, for doctests), so every warning shows up twice and functions that
  // only the tests call are reported as never used. Drop the dead-code
  // blocks, the duplicates, and the "generated N warnings" tallies.
  function tidyStderr(stderr) {
    const blocks = stderr.replace(/\r/g, '').split(/\n(?=warning|error|For more information)/);
    const seen = new Set();
    const kept = [];
    for (const block of blocks) {
      if (/^warning: .* is never (used|read|constructed)|^warning: unused .*dead_code|`#\[warn\(dead_code\)\]`/.test(block)) continue;
      if (/^warning: `playground` \((lib|bin)[^)]*\) generated \d+ warning/.test(block)) continue;
      const key = block.trim();
      if (!key || seen.has(key)) continue;
      seen.add(key);
      kept.push(block);
    }
    return kept.join('\n');
  }

  // The empty doctest run that follows the unit tests says nothing useful.
  function tidyStdout(stdout) {
    return stdout.replace(/\n+running 0 tests\n+test result: ok\. 0 passed;[^\n]*\n*$/, '\n');
  }

  function formatOutput(outcome) {
    const lines = (tidyStderr(outcome.stderr) + '\n' + tidyStdout(outcome.stdout)).split('\n');
    const out = [];
    for (const raw of lines) {
      const line = raw.replace(/\r$/, '');
      if (/^\s*(Compiling|Finished|Running|Doc-tests|Blocking|Downloading|Downloaded|Locking|Updating|Adding)\b/.test(line)) continue;
      if (/^error: test failed, to rerun pass/.test(line)) continue;
      if (line.trim() === '') { out.push(''); continue; }
      let cls = '';
      if (/^error(\[E\d+\])?:|^error:|\bFAILED\b|^failures:|panicked at|^thread '/.test(line)) cls = 'err';
      else if (/^warning/.test(line)) cls = 'warn';
      else if (/\.\.\. ok$|^test result: ok/.test(line)) cls = 'ok';
      else if (/^\s+-->|^\s+\|/.test(line)) cls = 'dim';
      out.push(cls ? '<span class="' + cls + '">' + linkifyErrors(line) + '</span>' : linkifyErrors(line));
    }
    return out.join('\n').replace(/\n{3,}/g, '\n\n').trim();
  }

  const STATUS_TEXT = {
    passed: 'All tests pass',
    failed: 'Tests failed',
    compile_error: 'Does not compile',
    timeout: 'Timed out',
    requirements_unmet: 'Tests pass, requirements not met',
  };

  // A dependency-free editor for when CodeMirror is not available (offline,
  // CDN blocked, or the page opened from the file system).
  function plainEditor(parent, opts) {
    const ta = el('textarea', { class: 'plain-editor', spellcheck: 'false', autocapitalize: 'off', autocomplete: 'off' });
    ta.value = opts.doc || '';
    ta.rows = Math.min(40, Math.max(14, ta.value.split('\n').length + 2));
    const insert = (text) => {
      ta.setRangeText(text, ta.selectionStart, ta.selectionEnd, 'end');
      ta.dispatchEvent(new Event('input'));
    };
    ta.addEventListener('input', () => { if (opts.onChange) opts.onChange(ta.value); });
    ta.addEventListener('keydown', (e) => {
      if (e.key === 'Tab' && !e.shiftKey) { e.preventDefault(); insert('    '); }
      else if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); if (opts.onRun) opts.onRun(); }
      else if (e.key === 'Enter') {
        e.preventDefault();
        const before = ta.value.slice(0, ta.selectionStart);
        const line = before.slice(before.lastIndexOf('\n') + 1);
        const indent = (line.match(/^\s*/) || [''])[0] + (/[{(\[]\s*$/.test(line) ? '    ' : '');
        insert('\n' + indent);
      }
    });
    parent.append(ta);
    return {
      getValue: () => ta.value,
      setValue: (text) => { ta.value = text; if (opts.onChange) opts.onChange(text); },
      focus: () => ta.focus(),
      destroy: () => ta.remove(),
    };
  }

  async function createEditor(parent, opts) {
    const E = window.Editor;
    if (E && E.ready) {
      await E.ready;
      if (E.mode === 'codemirror' && E.create) return E.create(parent, opts);
    }
    return plainEditor(parent, opts);
  }

  function debounce(fn, ms) {
    let t = null;
    return (...args) => { clearTimeout(t); t = setTimeout(() => fn(...args), ms); };
  }

  function renderExercise(ch, card, body, opts) {
    const ex = exerciseById(card.ref);
    const ui = exState(ex.id);
    const prog = exerciseProgress(ex.id);

    const attempts = el('span', { class: 'muted' }, 'Attempts: ' + prog.attempts);
    body.append(
      el('div', { class: 'row', style: 'margin-top:14px' },
        el('span', { class: 'exercise-kind' }, { fix: 'Fix the code', implement: 'Implement', write: 'Write it', project: 'Project stage' }[ex.kind] || ex.kind),
        attempts),
      el('div', { html: md.render(ex.description) }));

    // Editor
    let editor = null;
    const editorHost = el('div', { class: 'editor' });
    const saveSoon = debounce((text) => code.set(ex, text), 300);
    const currentSource = () => (editor ? editor.getValue() : code.get(ex));
    const openLink = el('a', { class: 'btn small', href: playgroundUrl(combined(code.get(ex), ex.tests)), target: '_blank', rel: 'noopener' }, 'Open in Playground ↗');
    const refreshOpenLink = debounce(() => { openLink.href = playgroundUrl(combined(currentSource(), ex.tests)); }, 500);

    const editorBar = el('div', { class: 'editor-bar' },
      el('code', null, ex.file),
      ex.tests ? el('span', null, '· shared by every stage of this project') : null,
      el('span', { class: 'spacer' }),
      el('button', {
        class: 'btn small', onclick: async () => {
          const ok = await confirmDialog('Reset the code?', 'Your edits to this file are replaced with the starting code.' + (ex.tests ? ' Other stages of this project use the same file.' : ''), 'Reset');
          if (!ok) return;
          code.reset(ex);
          if (editor) editor.setValue(ex.starter);
          toast('Code reset');
        },
      }, 'Reset code'),
      openLink);
    body.append(editorBar, editorHost);

    createEditor(editorHost, {
      doc: code.get(ex),
      onChange: (text) => { saveSoon(text); refreshOpenLink(); },
      onRun: () => run(),
    }).then((e) => {
      if (!document.body.contains(editorHost)) { e.destroy(); return; }
      editor = e;
    });

    if (ex.tests) {
      body.append(el('details', { class: 'tests' },
        el('summary', null, 'Stage tests (appended to your code when you run; read-only)'),
        el('pre', { class: 'code lang-rust', html: '<code>' + hl.rust(ex.tests) + '</code>' })));
    }

    // Run row
    const statusPill = el('span', { class: 'status-pill ' + (prog.last_status || '') },
      STATUS_TEXT[prog.last_status] || (prog.passed ? 'Passed' : 'Not run yet'));
    const term = el('div', { class: 'term' });
    const checks = el('ul', { class: 'checks' });
    const runBtn = el('button', { class: 'btn primary', onclick: () => run() }, '▶ Run tests');
    body.append(
      el('div', { class: 'row' },
        runBtn,
        el('span', { class: 'muted' }, 'Ctrl+Enter in the editor · compiles on play.rust-lang.org'),
        el('span', { class: 'spacer' }),
        statusPill),
      term, checks);

    function showOutcome(outcome) {
      term.innerHTML = formatOutput(outcome) || '<span class="dim">(no output)</span>';
      checks.innerHTML = '';
      for (const c of outcome.checks || []) checks.append(el('li', { class: c.ok ? '' : 'unmet' }, c.label));
      statusPill.className = 'status-pill ' + outcome.status;
      statusPill.textContent = STATUS_TEXT[outcome.status] || outcome.status;
    }
    if (ui.outcome) showOutcome(ui.outcome);

    async function run() {
      if (ui.running) return;
      ui.running = true;
      runBtn.disabled = true;
      const source = currentSource();
      code.set(ex, source);
      term.innerHTML = '<span class="dim">Compiling and testing on play.rust-lang.org…</span>';
      try {
        const r = await playground(combined(source, ex.tests), true);
        let status = classify(r);
        let checkList = [];
        if (status === 'passed') {
          checkList = extraChecks(ex.requires, source);
          if (checkList.some((c) => !c.ok)) status = 'requirements_unmet';
        }
        const outcome = { status, stdout: r.stdout || '', stderr: r.stderr || '', checks: checkList };
        ui.outcome = outcome;
        const wasDone = exerciseProgress(ex.id).passed;
        const award = recordRun(ex.id, ex.xp, status === 'passed', status);
        showOutcome(outcome);
        handleAward(award);
        refreshChapterStats(ch);
        if (status === 'passed') {
          const cardNode = $('#card-' + CSS.escape(card.id));
          if (cardNode) cardNode.classList.add('done', 'flash');
          if (!wasDone) {
            toast('Exercise complete: ' + ex.title, 'xp', 3000);
            unlockNext(ch, card);
            if (!$('.continue-row', body)) body.append(continueButton(ch, card, 'Continue'));
          }
        }
        renderSolutionRow();
        attempts.textContent = 'Attempts: ' + exerciseProgress(ex.id).attempts;
      } catch (e) {
        term.innerHTML = '<span class="err">' + md.escapeHtml(e.message) + '</span>';
      }
      ui.running = false;
      runBtn.disabled = false;
    }

    // Hints (free; revealed one at a time and remembered)
    const hintsBox = el('div', { class: 'hints' });
    const hintList = el('div');
    const hintBtn = el('button', { class: 'btn small', onclick: () => { revealHint(ex.id, shown() + 1); renderHints(); } });
    const shown = () => Math.min(exerciseProgress(ex.id).hints_revealed || 0, ex.hints.length);
    function renderHints() {
      hintList.innerHTML = '';
      ex.hints.slice(0, shown()).forEach((h, i) =>
        hintList.append(el('div', { class: 'hint' }, el('strong', null, 'Hint ' + (i + 1) + '. '), el('span', { html: md.inline(h) }))));
      const n = shown();
      if (ex.hints.length === 0) { hintBtn.style.display = 'none'; return; }
      if (n >= ex.hints.length) { hintBtn.disabled = true; hintBtn.textContent = 'No more hints'; }
      else hintBtn.textContent = n === 0 ? 'Show a hint (' + ex.hints.length + ' available)' : 'Next hint (' + (n + 1) + '/' + ex.hints.length + ')';
    }
    hintsBox.append(el('div', { class: 'row' }, hintBtn), hintList);
    body.append(hintsBox);
    renderHints();

    // Solution
    const solutionBox = el('div', { class: 'solution' });
    body.append(solutionBox);
    function renderSolutionRow() {
      solutionBox.innerHTML = '';
      const p = exerciseProgress(ex.id);
      if (ui.solution) {
        solutionBox.append(
          el('div', { class: 'row' },
            el('span', { class: 'muted' }, 'Reference solution. Read it, then write your own version from memory.'),
            el('span', { class: 'spacer' }),
            el('button', {
              class: 'btn small', onclick: async () => {
                const ok = await confirmDialog('Replace your code with the solution?', 'Your current edits to this file are lost.', 'Replace');
                if (!ok) return;
                code.set(ex, ex.solution);
                if (editor) editor.setValue(ex.solution);
              },
            }, 'Copy into editor')),
          el('pre', { class: 'code lang-rust', html: '<code>' + hl.rust(ui.solution) + '</code>' }));
        return;
      }
      if (p.attempts >= 2 || p.solution_revealed || p.passed) {
        solutionBox.append(el('button', {
          class: 'btn small', onclick: async () => {
            const ok = p.passed || p.solution_revealed || await confirmDialog('Reveal the solution?',
              'You will still be able to earn XP for this exercise, but only half of it. Hints are free, if you have not tried them.', 'Reveal');
            if (!ok) return;
            revealSolution(ex.id);
            ui.solution = ex.solution;
            renderSolutionRow();
          },
        }, p.passed ? 'Compare with the reference solution' : 'Show the solution'));
      } else {
        solutionBox.append(el('span', { class: 'muted' }, 'The solution unlocks after two attempts.'));
      }
    }
    renderSolutionRow();

    if (!opts.done) {
      body.append(el('div', { class: 'row' },
        el('span', { class: 'spacer' }),
        el('button', { class: 'link-btn', onclick: () => advance(ch, card) }, 'Skip for now →')));
    }
  }

  // ------------------------------------------------------------------
  // Routing & boot
  // ------------------------------------------------------------------

  function route() {
    const hash = location.hash.replace(/^#\/?/, '');
    const ch = state.course.chapters.find((c) => c.id === hash);
    state.chapterId = ch ? ch.id : null;
    renderSidebar();
    if (ch) renderChapter(ch); else renderHome();
    window.scrollTo({ top: 0 });
  }

  function boot() {
    if (!window.COURSE || !Array.isArray(window.COURSE.chapters)) {
      $('#content').innerHTML = '';
      $('#content').append(el('div', { class: 'error-box' },
        'Could not load the course data (data/course.js).\n\nIf you are running from a checkout, generate it with:\n  cargo run -p course -- build'));
      return;
    }
    state.course = window.COURSE;
    state.progress = normaliseProgress(storage.get(KEYS.progress, null)) || emptyProgress();

    // Mobile menu button.
    $('.brand').append(el('button', {
      class: 'btn small menu-btn', style: 'margin-left:auto',
      onclick: () => $('#sidebar').classList.toggle('open'),
    }, 'Chapters'));

    $('#export-progress').addEventListener('click', exportProgress);
    $('#import-progress').addEventListener('click', () => $('#import-file').click());
    $('#import-file').addEventListener('change', (e) => {
      const file = e.target.files && e.target.files[0];
      e.target.value = '';
      if (file) importProgress(file);
    });
    $('#reset-progress').addEventListener('click', async () => {
      const ok = await confirmDialog('Reset everything?', 'XP, answered cards, exercise history and the code in every editor are cleared from this browser. Export first if you want a copy.', 'Reset');
      if (!ok) return;
      state.progress = emptyProgress();
      saveProgress();
      code.clearAll();
      for (const k of storage.keys(KEYS.unlocked)) storage.remove(k);
      state.exercise = {};
      route();
      toast('Progress reset');
    });

    window.addEventListener('hashchange', route);
    route();
  }

  boot();
})();
